minimal_patch:
在 scripts/run-daily-tasks.mjs 的模型调用成功后，新增对 taskCommand 的调用以完成 claim 和 submit 状态流转。具体改动：

1. 文件顶部添加导入：
   import { taskCommand } from '../workers/pulse-worker/tasks.js';

2. 在 main() 内，读取 pulse 状态后加载或初始化 task_board：
   const pulseState = readJson(path.join(ROOT,'knowledge/results/pulse/latest.json'), null) || {};
   const taskState = await import('../workers/pulse-worker/tasks.js').then(m => m.seedTasks({ task_board: pulseState.task_board || [] }));

3. 在每个 CHANNELS 循环内，模型调用成功（res.ok 且产出通过完整性检查）后，紧接在 writeJson(memPath, mem) 之前插入：
   if (assignment?.id) {
     try {
       let cmdResult = taskCommand(taskState, { task_id: assignment.id, action: 'claim_task', agent: ch.agent }, 'daily-runner', CHANNELS.map(c=>c.agent));
       taskState = cmdResult.state;
       const evidencePath = `data/memory/${ch.agent}.json`;
       const evidenceSha = crypto.createHash('sha256').update(fs.readFileSync(path.join(ROOT, evidencePath), 'utf8')).digest('hex');
       cmdResult = taskCommand(taskState, { task_id: assignment.id, action: 'submit_task', agent: ch.agent, evidence_path: `data/${ch.agent}.json`, evidence_sha256: evidenceSha }, 'daily-runner', CHANNELS.map(c=>c.agent));
       taskState = cmdResult.state;
     } catch (e) { /* 记录但不中断主流程 */ console.warn(`[task-command] ${ch.agent}: ${e.message}`); }
   }

4. 循环结束后持久化任务板状态：
   writeJson(path.join(ROOT,'knowledge/results/pulse/latest.json'), { ...pulseState, task_board: taskState.task_board, updated_at: nowCST() });
